# Local one-time bootstrap; uses only the official Gradle 8.9 distribution.
# A Gradle Wrapper JAR is generated by Gradle itself, not downloaded independently.
# Uses no Git, GitHub, hosted builds, or private credentials.
$ErrorActionPreference = 'Stop'
$project = Split-Path -Parent $MyInvocation.MyCommand.Path
$version = '8.9'
$zipUrl = 'https://downloads.gradle.org/distributions/gradle-8.9-bin.zip'
# Official Gradle release checksum: https://gradle.org/release-checksums/
$expected = 'd725d707bfabd4dfdc958c624003b3c80accc03f7037b5122c4b1d0ef15cecab'

if (-not $env:JAVA_HOME -or -not (Test-Path (Join-Path $env:JAVA_HOME 'bin\java.exe'))) {
    $candidates = @(
        (Join-Path $env:ProgramFiles 'Android\Android Studio\jbr'),
        (Join-Path $env:LOCALAPPDATA 'Programs\Android Studio\jbr')
    )
    $jbr = $candidates | Where-Object { Test-Path (Join-Path $_ 'bin\java.exe') } | Select-Object -First 1
    if (-not $jbr) { throw 'Install Android Studio first; its bundled Java runtime could not be found.' }
    $env:JAVA_HOME = $jbr
}
Write-Host "Using Java: $env:JAVA_HOME"

$cache = Join-Path $env:LOCALAPPDATA 'GlassesDownloader-BuildTools'
$distZip = Join-Path $cache 'gradle-8.9-bin.zip'
$gradle = Join-Path $cache 'gradle-8.9\bin\gradle.bat'
New-Item -ItemType Directory -Force -Path $cache | Out-Null
if (-not (Test-Path $distZip)) {
    Write-Host 'Downloading official Gradle 8.9 distribution (~130 MB)...'
    Invoke-WebRequest -UseBasicParsing -Uri $zipUrl -OutFile $distZip
}
$actual = (Get-FileHash -LiteralPath $distZip -Algorithm SHA256).Hash.ToLowerInvariant()
if ($actual -ne $expected) {
    Remove-Item -LiteralPath $distZip -Force -ErrorAction SilentlyContinue
    throw "Gradle ZIP checksum mismatch. Expected $expected, got $actual. Download discarded."
}
Write-Host 'Gradle distribution SHA256 verified.' -ForegroundColor Green
if (-not (Test-Path $gradle)) {
    Write-Host 'Extracting Gradle distribution locally...'
    Expand-Archive -LiteralPath $distZip -DestinationPath $cache -Force
}
if (-not (Test-Path $gradle)) { throw 'Unable to locate Gradle after extraction.' }

# Generate the standard scripts/JAR using an empty, offline bootstrap Gradle project
# so the Android plugin dependencies are not needed for this preparatory step.
$tmp = Join-Path $env:TEMP ('GlassesDownloader-wrapper-' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $tmp -Force | Out-Null
try {
    Set-Content -LiteralPath (Join-Path $tmp 'settings.gradle') -Value "rootProject.name = 'wrapper-bootstrap'" -Encoding Ascii
    Push-Location $tmp
    try {
        & $gradle --offline --no-daemon wrapper --gradle-version $version --distribution-type bin
        if ($LASTEXITCODE -ne 0) { throw "Gradle wrapper generation exited with code $LASTEXITCODE" }
    } finally { Pop-Location }
    $target = Join-Path $project 'gradle\wrapper'
    New-Item -ItemType Directory -Force -Path $target | Out-Null
    Copy-Item -LiteralPath (Join-Path $tmp 'gradle\wrapper\gradle-wrapper.jar') -Destination (Join-Path $target 'gradle-wrapper.jar') -Force
    Copy-Item -LiteralPath (Join-Path $tmp 'gradlew.bat') -Destination (Join-Path $project 'gradlew.bat') -Force
    Copy-Item -LiteralPath (Join-Path $tmp 'gradlew') -Destination (Join-Path $project 'gradlew') -Force
} finally {
    Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
}
# Keep the project’s already configured distribution URL at downloads.gradle.org.
$wrapperJar = Join-Path $project 'gradle\wrapper\gradle-wrapper.jar'
$jarHash = (Get-FileHash -LiteralPath $wrapperJar -Algorithm SHA256).Hash.ToLowerInvariant()
# Gradle-published 8.9 wrapper-JAR checksum (same official checksums page above).
if ($jarHash -ne '498495120a03b9a6ab5d155f5de3c8f0d986a449153702fb80fc80e134484f17') {
    Remove-Item -LiteralPath $wrapperJar -Force
    throw "Generated wrapper JAR checksum mismatch: $jarHash"
}
Write-Host 'Official Gradle wrapper generated and verified.' -ForegroundColor Green
Write-Host 'Next: Android Studio > Open > select this GlassesDownloader folder.'
